def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))
    fill_color = min(objects, key=lambda o: len(o[1]))[0]
    candidates = []
    for color, cells in objects:
        r0 = min(r for r,c in cells); r1 = max(r for r,c in cells)
        c0 = min(c for r,c in cells); c1 = max(c for r,c in cells)
        shape = [[bg]*(c1-c0+1) for _ in range(r1-r0+1)]
        for r,c in cells:
            shape[r-r0][c-c0] = color
        sh, sw = len(shape), len(shape[0])
        outside = set()
        stack = []
        for y in range(sh):
            for x in range(sw):
                if (y in (0, sh-1) or x in (0, sw-1)) and shape[y][x] == bg:
                    stack.append((y,x)); outside.add((y,x))
        while stack:
            y,x = stack.pop()
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx = y+dy,x+dx
                if 0 <= ny < sh and 0 <= nx < sw and (ny,nx) not in outside and shape[ny][nx] == bg:
                    outside.add((ny,nx)); stack.append((ny,nx))
        holes = [(y,x) for y in range(sh) for x in range(sw) if shape[y][x] == bg and (y,x) not in outside]
        if holes:
            for y,x in holes:
                shape[y][x] = fill_color
            candidates.append((sh*sw, shape))
    return max(candidates, key=lambda x: x[0])[1]
